*{box-sizing:border-box} :root{--ink:#172629;--muted:#758487;--paper:#f6f7f3;--line:#e6e9e3;--green:#b9da7a;--deep:#263b32;--orange:#f0a75c} html,body{margin:0;min-height:100%;font-family:'DM Sans',sans-serif;color:var(--ink);background:#e8ede7}body{padding:18px}.app-shell{max-width:1600px;min-height:calc(100vh - 36px);margin:auto;background:var(--paper);border:1px solid rgba(32,55,47,.09);box-shadow:0 24px 80px rgba(34,54,46,.13);display:flex;flex-direction:column;overflow:hidden}.topbar{height:66px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fbfcf9;border-bottom:1px solid var(--line);flex-shrink:0}.brand{display:flex;align-items:center;gap:11px;color:#21332d;text-decoration:none;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:.065em}.brand-light{font-weight:500;color:#739056}.brand-mark{width:26px;height:26px;position:relative;display:block}.brand-mark i{position:absolute;width:14px;height:14px;transform:rotate(30deg) skewY(30deg) scaleX(.86);background:#80a35a;left:2px;top:7px;clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%)}.brand-mark i:nth-child(2){left:10px;top:2px;background:#badb79}.brand-mark i:nth-child(3){left:11px;top:12px;background:#4f7451}.world-title{display:flex;gap:9px;align-items:center;font:500 10px 'DM Mono',monospace;letter-spacing:.13em;color:#3c554b}.live-dot,.save-dot,.clock-dot{width:6px;height:6px;border-radius:50%;background:#a7cd6d;box-shadow:0 0 0 3px #eaf3dc}.title-divider{color:#c4ccc2}.world-seed{color:#a1aaa2}.top-actions{display:flex;align-items:center;gap:10px}.day-pill{height:30px;padding:0 10px;border:1px solid #e8ebe4;border-radius:4px;display:flex;align-items:center;gap:7px;color:#46584d;font:500 9px 'DM Mono',monospace;letter-spacing:.08em}.sun-icon{font-size:13px;color:#e8ad58}.weather{color:#a0a9a0;border-left:1px solid #e6e9e2;padding-left:8px}.icon-btn{width:30px;height:30px;border:1px solid #e8ebe4;background:transparent;color:#688074;border-radius:4px;font-size:15px;cursor:pointer}.icon-btn:hover{background:#edf3e6}.game-layout{display:grid;grid-template-columns:244px minmax(400px,1fr) 315px;flex:1;min-height:620px}.left-rail,.right-rail{background:#fbfcf9;padding:20px 18px;position:relative;z-index:2}.left-rail{border-right:1px solid var(--line)}.right-rail{border-left:1px solid var(--line)}.profile-card{display:flex;align-items:center;padding:0 0 18px;border-bottom:1px solid var(--line);gap:10px}.avatar{height:38px;width:38px;background:#d8e6bf;border-radius:50%;position:relative;display:flex;align-items:center;justify-content:center;color:#566b43;overflow:hidden}.avatar:before{content:'';position:absolute;left:8px;top:14px;width:22px;height:24px;border-radius:9px 9px 5px 5px;background:#efc99a}.avatar-cap{position:absolute;top:8px;left:7px;width:24px;height:10px;background:#5d7c55;border-radius:8px 8px 2px 2px;z-index:1}.avatar-face{z-index:2;margin-top:8px;font-size:12px}.profile-copy{display:grid;gap:3px}.eyebrow{font:500 9px 'DM Mono',monospace;color:#8b9b8a;letter-spacing:.14em}.profile-copy strong{font:600 12px 'Space Grotesk',sans-serif}.rank{margin-left:auto;background:#edf2e8;color:#728b5b;padding:5px 6px;font:500 8px 'DM Mono',monospace;border-radius:3px}.rail-heading,.section-heading{display:flex;align-items:center;justify-content:space-between;margin:21px 0 10px;font:500 9px 'DM Mono',monospace;color:#819088;letter-spacing:.12em}.tiny-count{color:#b0b9af;font-size:8px}.quest-card{background:#edf3e5;border:1px solid #e2ebd5;border-radius:6px;padding:13px 12px 11px;position:relative;overflow:hidden}.quest-card:after{content:'';position:absolute;width:95px;height:95px;border:1px solid rgba(156,187,115,.16);border-radius:50%;right:-45px;top:-48px;box-shadow:0 0 0 13px rgba(156,187,115,.05),0 0 0 28px rgba(156,187,115,.04)}.quest-icon{width:24px;height:24px;border-radius:5px;display:grid;place-items:center;background:#dce9c7;color:#84a457;font-size:14px;float:left;margin:0 9px 0 0}.quest-kicker{font:500 8px 'DM Mono',monospace;letter-spacing:.13em;color:#8a9b7a;padding-top:2px}.quest-content h2{font:600 18px/1.05 'Space Grotesk',sans-serif;margin:7px 0 6px;letter-spacing:-.03em;color:#2d4134}.quest-content p{font-size:10px;line-height:1.55;color:#77846e;margin:0;max-width:175px}.quest-progress{display:flex;justify-content:space-between;align-items:center;margin-top:13px;font:500 9px 'DM Mono',monospace;color:#788970}.progress-line{height:4px;background:#dce6d0;border-radius:4px;width:75%;overflow:hidden}.progress-line span{display:block;width:0;height:100%;background:#91b365;transition:width .3s}.quest-costs{display:flex;gap:6px;margin-top:10px}.cost-chip{padding:4px 6px;background:#f7f9f4;border-radius:3px;display:flex;align-items:center;gap:5px;color:#798573;font:500 9px 'DM Mono',monospace}.material{display:inline-block;width:8px;height:8px}.wood-small{background:#b97b4c}.stone-small{background:#899698;transform:rotate(45deg) scale(.8)}.crystal-small{background:#85c9c4;clip-path:polygon(50% 0,100% 35%,75% 100%,25% 100%,0 35%)}.side-section{padding:1px 0 12px;border-bottom:1px solid var(--line)}.section-heading{margin:20px 0 7px}.text-action{border:0;background:transparent;font:500 8px 'DM Mono',monospace;color:#a6afa5;cursor:pointer;letter-spacing:.08em}.resource-row{height:32px;display:flex;align-items:center;gap:8px;font-size:10px;color:#75827a}.resource-row strong{margin-left:auto;color:#34443c;font:600 11px 'DM Mono',monospace}.resource-unit{color:#b0b9b0;font-size:8px}.resource-symbol{width:18px;height:18px;border-radius:4px;display:grid;place-items:center;font-size:11px}.wood-symbol{color:#a87346;background:#f4e9dc}.stone-symbol{color:#748687;background:#e9eeee}.crystal-symbol{color:#63aba5;background:#e0f1ee}.fiber-symbol{color:#92a85e;background:#eef3e2}.tip-card{display:flex;gap:9px;margin:17px 0 13px;padding:10px 9px;background:#f4f6ef;border:1px solid #edf0e7;border-radius:4px}.tip-spark{font-size:14px;color:#a7c477}.tip-card p{margin:5px 0 0;color:#7