;color:#f9e3a7;font-size:22px;text-shadow:0 0 13px #dca354;background:linear-gradient(135deg,#799765 0 35%,#55744e 36% 68%,#425e46 69%);clip-path:polygon(50% 0,100% 37%,80% 100%,20% 100%,0 37%);filter:drop-shadow(3px 5px 0 rgba(68,93,61,.25))}.recipe-info{padding:10px 11px 11px}.recipe-name-row{display:flex;align-items:center;gap:6px}.recipe-name-row h3{margin:0;font:600 12px 'Space Grotesk',sans-serif;letter-spacing:-.02em}.new-tag,.craft-level{padding:3px 5px;border-radius:2px;background:#eff4e5;color:#8ca568;font:500 7px 'DM Mono',monospace;letter-spacing:.07em}.recipe-info p{margin:4px 0 8px;color:#98a199;font-size:9px}.recipe-needs{display:flex;gap:10px;margin-bottom:9px}.recipe-needs span{display:flex;align-items:center;gap:4px;color:#7b887c;font:500 9px 'DM Mono',monospace}.recipe-needs b{font-weight:500}.recipe-needs i{display:inline-block;width:8px;height:8px;border-radius:1px}.need-wood{background:#b97b4c}.need-stone{background:#8c9a9b;transform:rotate(45deg) scale(.82)}.need-crystal{background:#79c6be;clip-path:polygon(50% 0,100% 35%,75% 100%,25% 100%,0 35%)}.need-fiber{background:#a2bc70}.craft-btn{height:26px;width:100%;display:flex;align-items:center;justify-content:space-between;padding:0 8px;background:#f5f7f1;border:1px solid #e7ebe1;border-radius:3px;color:#69805b;font:500 8px 'DM Mono',monospace;letter-spacing:.06em;cursor:pointer}.craft-btn:hover:not(:disabled){background:#eaf1de;border-color:#d7e5c4}.craft-btn:disabled{color:#a8b1a5;cursor:not-allowed;background:#f7f8f5}.craft-btn span{font-size:12px}.primary-craft{background:#ebf2df;color:#83966c;border-color:#e1ead5}.compact-recipe{display:grid;grid-template-columns:64px 1fr;min-height:102px}.compact-recipe .recipe-visual{height:100%;font-size:24px}.axe-visual{background:#edf1e8;color:#85956c}.camp-visual{background:#f3eade;color:#c2956b}.torch-visual{background:#f7ede0;color:#d09a56}.compact-recipe .recipe-info{padding:9px 9px 8px}.compact-recipe .recipe-info p{font-size:8px;margin:3px 0 7px}.compact-recipe .recipe-needs{gap:9px;margin-bottom:7px}.compact-recipe .recipe-name-row h3{font-size:11px}.compact-recipe .craft-btn{height:23px}.bench-footer{margin-top:14px;padding-top:11px;border-top:1px solid var(--line);display:flex;gap:7px;align-items:center;color:#a1aaa0;font-size:9px}.bench-star{color:#afc77f}.footer{height:32px;padding:0 17px 0 20px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#91a096;font:500 8px 'DM Mono',monospace;letter-spacing:.08em;flex-shrink:0}.footer-muted{color:#b4bdb4}.save-state{display:flex;align-items:center;gap:7px;color:#95a594}.save-dot{width:5px;height:5px;box-shadow:none}.footer-version{color:#b5beb5}.modal-backdrop{position:fixed;inset:0;z-index:20;background:rgba(21,37,29,.48);display:grid;place-items:center;padding:20px;backdrop-filter:blur(4px)}.modal-backdrop[hidden]{display:none}.modal{position:relative;width:min(410px,100%);padding:31px;background:#fbfcf8;border:1px solid #e7ebe1;border-radius:8px;box-shadow:0 20px 80px #10201544}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;font-size:22px;color:#9ba79a;cursor:pointer}.modal h2{font:600 26px/1.05 'Space Grotesk',sans-serif;letter-spacing:-.04em;margin:12px 0}.modal p{font-size:12px;line-height:1.7;color:#77847a}.modal-controls{display:flex;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:16px 0;margin:20px 0}.modal-controls div{display:grid;justify-items:center;gap:6px}.modal-controls .keycap{background:#f0f3eb;border-color:#e1e7db;color:#687864;padding:5px 7px;font-size:8px}.modal-controls small{font:500 7px 'DM Mono',monospace;color:#9ba69b;letter-spacing:.1em}.modal-play{width:100%;height:39px;border:0;border-radius:4px;background:#728e56;color:white;font:500 9px 'DM Mono',monospace;letter-spacing:.11em;cursor:pointer}.modal-play:hover{background:#637f49}.modal-play span{float:right;font-size:15px;margin-top:-3px}
