@media(max-width:850px){.topbar{height:56px;padding:0 15px}.world-title{display:none}.game-layout{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(520px,65vh) auto;min-height:0}.play-area{grid-row:1;min-height:520px}.left-rail{grid-row:2;border:0;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:12px 16px;padding:16px}.profile-card{grid-column:1/-1;padding-bottom:12px}.rail-heading{display:none}.quest-card{grid-column:1}.side-section{grid-column:2;grid-row:2/4;border:0;padding:0}.tip-card{grid-column:1;margin:0}.journal-btn{grid-column:1}.right-rail{grid-row:3;border:0;border-top:1px solid var(--line);padding:20px}.recipe-list{display:grid;grid-template-columns:1fr 1fr}.recipe-card:first-child{grid-row:span 2}.compact-recipe{min-height:96px}.bench-footer{margin-top:10px}.footer{height:30px}.scene-hud{top:52px}}
@media(max-width:540px){.topbar{padding:0 12px}.brand{font-size:12px}.day-pill{height:27px;padding:0 7px}.weather{display:none}.top-actions{gap:6px}.icon-btn{width:27px;height:27px}.game-layout{grid-template-rows:minmax(480px,65vh) auto}.play-area{min-height:480px}.hotbar-wrap{bottom:44px;width:min(310px,88%)}.hotbar{height:55px}.control-hint{display:none}.mobile-action{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;z-index:5;border:1px solid rgba(255,255,255,.42);background:rgba(36,59,45,.76);color:#f7f8ef;border-radius:4px;padding:7px 11px;font:500 8px 'DM Mono',monospace;letter-spacing:.1em}.mobile-action span{font-size:13px}.left-rail{grid-template-columns:1fr;gap:10px;padding:13px}.profile-card{grid-column:1}.quest-card{grid-column:1}.side-section{grid-column:1;grid-row:auto;display:grid;grid-template-columns:1fr 1fr;column-gap:12px}.section-heading{grid-column:1/-1;margin:7px 0}.resource-row{height:27px}.tip-card{grid-column:1}.journal-btn{grid-column:1}.right-rail{padding:16px 13px}.recipe-list{gap:7px}.compact-recipe{grid-template-columns:46px 1fr;min-height:102px}.compact-recipe .recipe-info{padding:7px 6px}.compact-recipe .recipe-name-row h3{font-size:10px}.recipe-info p{font-size:8px}.recipe-card:first-child .recipe-visual{height:58px}.recipe-card:first-child .recipe-info{padding:8px}.recipe-card:first-child .recipe-name-row h3{font-size:11px}.recipe-card:first-child .recipe-info p{font-size:8px}.recipe-needs{gap:7px}.footer{padding:0 10px;font-size:7px}.footer-version{display:none}.coordinates{font-size:8px}.scene-topline{left:10px;right:10px}.scene-hud{left:10px;right:10px}.modal{padding:26px 22px}}

(() => {
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const state = {
    size: 15, player: {x: 7, y: 7}, inv: {wood: 0, stone: 0, crystal: 0, fiber: 0},
    day: 1, minutes: 8 * 60 + 24, selected: 0, hasAxe: false, hasTorch: false,
    beacon: false, camp: false, toastTimer: 0, moveTimer: 0, target: null, sound: true, seed: 414,
    objects: [], tiles: [], screenObjects: [], particles: [], lastTime: 0, time: 0
  };
  const recipes = {
    beacon: {cost:{wood:8,stone:6,crystal:3}}, axe:{cost:{wood:3,stone:2}},
    camp:{cost:{wood:2,fiber:2}}, torch:{cost:{wood:1,fiber:2}}
  };
  const names = {wood:'softwood',stone:'stone',crystal:'star crystal',fiber:'wild fiber'};
  const keyMap = {KeyW:[0,-1],ArrowUp:[0,-1],KeyS:[0,1],ArrowDown:[0,1],KeyA:[-1,0],ArrowLeft:[-1,0],KeyD:[1,0],ArrowRight:[1,0]};
  let width = 900, height = 650, dpr = 1;

  function rand(){ state.seed=(state.seed*1664525+1013904223)>>>0; return state.seed/4294967296; }
  function inside(x,y){ return x>=0&&y>=0&&x<state.size&&y<state.size; }
  function land(x,y){ const dx=(x-7)/7.6,dy=(y-7)/7.4; return dx*dx+dy*dy<1.04 && !(x<1||y<1||x>13||y>13); }
  function load(){
    try {const saved=JSON.parse(localStorage.getItem('polygon-wild-save')); if(saved&&saved.inv){Object.assign(state.inv,saved.inv);state.day=saved.day||1;state.beacon=!!saved.beacon;state.hasAxe=!!saved.hasAxe;state.hasTorch=!!saved.hasTorch;state.camp=!!saved.camp; if(saved.player){state.player.x=saved.player.x;state.player.y=saved.player.y;}}}catch(_){ }
  }
  function save(){try{localStorage.setItem('polygon-wild-save',JSON.stringify({inv:state.inv,day:state.day,beacon:state.beacon,hasAxe:state.hasAxe,hasTorch:state.hasTorch,camp:state.camp,player:state.player}));}catch(_){}}
  function makeWorld(){
    state.tiles=[];state.objects=[];state.seed=414;
    for(let y=0;y<state.size;y++) for(let x=0;x<state.size;x++){
      if(!land(x,y))continue;
      const edge=((x-7)/7.4)**2+((y-7)/7.3)**2>.79;
